        return -1
    if root.data == target:
        return 0
    left_dist = distance(root.left, target)
    if left_dist != -1:
        return left_dist + 1
    right_dist = distance(root.right, target)
    if right_dist != -1:
        return right_dist + 1
    return -1

def find_k_distance_nodes(root, target, k):
