        return find_k_distance_nodes_from_target(root, k)
    left_result = find_k_distance_nodes(root.left, target, k)
    if left_result:
        return left_result
    right_result = find_k_distance_nodes(root.right, target, k)
    if right_result:
        return right_result
    return []

